assignments.value:
={{ (() => {
  const parts = $('Normalize mediator request').item.json.smsText.split('|').map(part => part.trim());
  const confidentiality = (parts[5] || 'STANDARD').toUpperCase();
  return (parts.length === 5 || parts.length === 6)
    && parts[0].toUpperCase() === 'NEW'
    && parts[1].length > 0
    && ['FAMILY', 'COMMUNITY'].includes((parts[2] || '').toUpperCase())
    && parts[3].length >= 5
    && ['NORMAL', 'URGENT'].includes((parts[4] || '').toUpperCase())
    && ['STANDARD', 'HIGH'].includes(confidentiality);
})() }}

={{ (() => {
  const parts = $('Normalize mediator request').item.json.smsText.split('|').map(part => part.trim());
  if (parts.length !== 5 && parts.length !== 6) return 'Use: NEW | location | FAMILY or COMMUNITY | short issue | NORMAL or URGENT | optional STANDARD or HIGH.';
  if (!parts[1]) return 'Add the general location after NEW.';
  if (!['FAMILY', 'COMMUNITY'].includes((parts[2] || '').toUpperCase())) return 'Category must be FAMILY or COMMUNITY.';
  if (!parts[3] || parts[3].length < 5) return 'Add a short neutral description of the issue.';
  if (!['NORMAL', 'URGENT'].includes((parts[4] || '').toUpperCase())) return 'Urgency must be NORMAL or URGENT.';
  if (parts[5] && !['STANDARD', 'HIGH'].includes(parts[5].toUpperCase())) return 'Confidentiality must be STANDARD or HIGH.';
  return '';
})() }}

={{ (() => {
  const parts = $('Normalize mediator request').item.json.smsText.split('|').map(part => part.trim());
  return parts.length === 4
    && parts[0].toUpperCase() === 'UPDATE'
    && /^MLI-\d{4}-[A-Z0-9]+$/.test((parts[1] || '').toUpperCase())
    && ['MEDIATION', 'FOLLOW-UP', 'AGREEMENT', 'OTHER'].includes((parts[2] || '').toUpperCase())
    && parts[3].length >= 5;
})() }}

={{ (() => {
  const parts = $('Normalize mediator request').item.json.smsText.split('|').map(part => part.trim());
  if (parts.length !== 4) return 'Use: UPDATE | case reference | MEDIATION, FOLLOW-UP, AGREEMENT, or OTHER | short update.';
  if (!/^MLI-\d{4}-[A-Z0-9]+$/.test((parts[1] || '').toUpperCase())) return 'Add a valid case reference, for example MLI-2026-001247.';
  if (!['MEDIATION', 'FOLLOW-UP', 'AGREEMENT', 'OTHER'].includes((parts[2] || '').toUpperCase())) return 'Update type must be MEDIATION, FOLLOW-UP, AGREEMENT, or OTHER.';
  if (!parts[3] || parts[3].length < 5) return 'Add a short neutral update.';
  return '';
})() }}

parameters.responseBody:
={{ $('Find case for UPDATE').item.json.case_id
