assignments.value:
={{ (() => {
  // Read the case once and collect all matching updates.
  const caseRow = $('Find case for SUMMARY').first().json;
  const updates = $('Find updates for SUMMARY').all()
    .map(item => item.json)
    .filter(row => row.update_id)
    .sort((a, b) => String(b.logged_at || '').localeCompare(String(a.logged_at || '')));

  // HIGH or SENSITIVE cases must not expose details in an SMS reply.
  const latest = updates[0] || null;
  const restricted =
    String(caseRow.confidentiality || '').toUpperCase() === 'HIGH'
    || String(caseRow.sensitivity || '').toUpperCase() === 'SENSITIVE';
  const location = restricted ? 'Restricted' : (caseRow.location || 'Not set');
  const issue = restricted
    ? 'Restricted — contact the record keeper'
    : (caseRow.reported_issue_short || 'Not set');
  const latestUpdate = !latest
    ? 'None recorded'
    : restricted
      ? (latest.update_type || 'UPDATE') + ' on ' + String(latest.logged_at || '').slice(0, 10)
      : (latest.short_update || latest.update_type || 'Update recorded');

  return [
    (caseRow.case_id || 'UNKNOWN') + ' | ' + (caseRow.category || 'UNSET') + ' | ' + (caseRow.status || 'UNSET'),
    'Urgency: ' + (caseRow.urgency || 'UNSET'),
    'Location: ' + location,
    'Participants: ' + (restricted ? 'Party A and Party B' : 'See protected case record'),
    'Reported issue: ' + issue,
    'Previous attempts: ' + (caseRow.previous_attempts_count ?? 0),
    'Updates: ' + updates.length,
    'Latest update: ' + latestUpdate,
    'Last action: ' + (caseRow.last_action_short || 'Not set'),
    'Next follow-up: ' + (caseRow.next_follow_up_date || 'Not set'),
    'Confidentiality: ' + (caseRow.confidentiality || 'STANDARD')
  ].join('\n');
})() }}

parameters.responseBody:
={{ (() => {
  const details = $('Prepare NEW contact guidance').item.json;
  return {
    saved: true,
    alert_sent: false,
    case_id: details.case_id,
    urgency: details.urgency,
    contact_found: details.contact_found,
    message: details.urgency === 'URGENT'
      ? details.mediator_reply + ' The private record-keeper alert failed, so contact the record keeper directly.'
      : 'Case ' + details.case_id + ' saved, but the private record-keeper alert failed. Contact the record keeper directly.'
  };
})() }}

value.message_text:
={{ (() => {
  const command = $('Prepare command').item.json.command;
  if (command === 'NEW') return $('Prepare NEW contact guidance').item.json.mediator_reply;
  if (command === 'UPDATE') {
    const u = $('Prepare UPDATE').item.json;
    return 'Update for ' + u.case_id + ' saved. The record keeper has been alerted.';
  }
  if (command === 'SUMMARY') return $('Prepare masked SUMMARY').first().json.summary;
  if (command === 'STATUS') {
    const c = $('Find case for STATUS').first().json;
    return c.case_id + ' | ' + (c.status || 'UNSET')
      + '\nUrgency: ' + (c.urgency || 'UNSET')
      + '\nRecord keeper: ' + (c.record_keeper_status || 'Not set')
      + '\nLast action: ' + (c.last_action_short || 'Not set')
      + '\nNext follow-up: ' + (c.next_follow_up_date || 'Not set')
      + (c.closed_at ? '\nClosed: ' + c.closed_at : '');
  }
  if (command === 'HELP') return 'Commands: NEW, UPDATE, SUMMARY, STATUS, or HELP.';
  return 'Command not recognized. Send HELP.';
})() }}

