={{ (() => {
  const c = $('Prepare NEW case').item.json;
  if (c.urgency !== 'URGENT') {
    return 'Case ' + c.case_id + ' saved. The record keeper has been alerted and will contact you. Do not send names or detailed allegations by SMS.';
  }
  const active = String($json.active ?? '').toUpperCase();
  const found = active === 'TRUE'
    && Boolean($json.local_authority_name)
    && Boolean($json.local_authority_phone_e164)
    && Boolean($json.peace_committee_leader_name)
    && Boolean($json.peace_committee_leader_phone_e164);
  if (!found) {
    return 'URGENT case ' + c.case_id + ' saved. Contact the local authority and peace-committee leader now using your organisation’s urgent-contact procedure. Their contacts are not configured for ' + c.location + '. Do not send names or detailed allegations by SMS.';
  }
  return 'URGENT case ' + c.case_id + ' saved. Contact ' + $json.local_authority_name + ' at ' + $json.local_authority_phone_e164 + ' and ' + $json.peace_committee_leader_name + ' at ' + $json.peace_committee_leader_phone_e164 + ' now. Do not send names or detailed allegations by SMS.';
})() }}

={{ (() => {
  const c = $('Prepare NEW case').item.json;
  const clean = value => String(value ?? '').replace(/[&<>]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' })[char]);
  const urgent = c.urgency === 'URGENT';
  const active = String($json.active ?? '').toUpperCase();
  const found = urgent
    && active === 'TRUE'
    && Boolean($json.local_authority_name)
    && Boolean($json.local_authority_phone_e164)
    && Boolean($json.peace_committee_leader_name)
    && Boolean($json.peace_committee_leader_phone_e164);
  let message = (urgent ? '⚠️ <b>URGENT NEW CASE</b>' : '<b>New case</b>')
    + '\nCase: ' + clean(c.case_id)
    + '\nCategory: ' + clean(c.category)
    + '\nUrgency: ' + clean(c.urgency)
    + '\nGeneral location: ' + clean(c.location);
  if (urgent && found) {
    message += '\n\nLocal authority: ' + clean($json.local_authority_name) + ' — ' + clean($json.local_authority_phone_e164)
      + '\nPeace-committee leader: ' + clean($json.peace_committee_leader_name) + ' — ' + clean($json.peace_committee_leader_phone_e164)
      + '\n\nAction: Call the reporting mediator now. Confirm they contact both people immediately, then complete the protected case record.';
  } else if (urgent) {
    message += '\n\nUrgent contacts: Not configured or the lookup is unavailable for this location.'
      + '\n\nAction: Call the reporting mediator now and use the organisation’s urgent-contact procedure. Then complete the protected case record.';
  } else {
    message += '\n\nAction: Call the reporting mediator and complete the protected case record.';
  }
  return message;
})() }}

={{ (() => {
  const c = $('Prepare NEW case').item.json;
  const steps = [
    '1. Separate reported information from information verified by a mediator or agreed by the parties.',
    '2. Record Party A and Party B perspectives separately and neutrally.',
    '3. Record the triggering incident, previous related incidents, and earlier resolution attempts.',
    '4. Record any agreement, whether each party accepted it, and the next follow-up date.',
    '5. Record confidentiality and safety notes, including what may or may not be shared.'
  ];
  if (c.category === 'FAMILY') {
    steps.push('6. Confirm that participation is voluntary and whether separate conversations are needed.');
  } else {
    steps.push('6. Confirm which community groups or representatives are involved and who may speak for them.');
  }
  if (c.confidentiality === 'HIGH') {
    steps.push('7. Use Party A and Party B codes. Keep names and phone numbers only in Identifying Details.');
  }
  if (c.urgency === 'URGENT') {
    steps.push((c.confidentiality === 'HIGH' ? '8.' : '7.') + ' Confirm contact with both designated urgent contacts and record what information was shared.');
  }
  return steps.join('\n');
})() }}

